// Decodes the embedded CSV and returns one item per row for the Sheets append.
const b64 = "Y2xpZW50X2lkLGNsaWVudF9uYW1lLHN0cmF0ZWd5X2lkLHN0YXR1cyxkYXRlX3VwZGF0ZWQsZXN0X2FubnVhbF9zYXZpbmdzLG5vdGVzCg==";
const csv = Buffer.from(b64, "base64").toString("utf8");
function parseCSV(text) {
  const rows = []; let i = 0, field = "", row = [], inQ = false;
  while (i < text.length) {
    const c = text[i];
    if (inQ) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i += 2; continue; } inQ = false; i++; continue; }
      field += c; i++; continue;
    }
    if (c === '"') { inQ = true; i++; continue; }
    if (c === ',') { row.push(field); field = ""; i++; continue; }
    if (c === '\r') { i++; continue; }
    if (c === '\n') { row.push(field); rows.push(row); row = []; field = ""; i++; continue; }
    field += c; i++;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows;
}
const rows = parseCSV(csv).filter(r => r.length > 1 || (r.length === 1 && r[0] !== ""));
const headers = rows.shift();
if (!rows.length) { return [{ json: Object.fromEntries(headers.map(h => [h, ""])) }]; }
